SELECT customer_id, total_spent
FROM CustomerTotals
WHERE total_spent > (
  SELECT AVG(total_spent)
  FROM CustomerTotals
);

SELECT customer_id, total_spent
FROM CustomerTotals
WHERE AVG(total_spent) > total_spent;

CREATE VIEW HighSpenders AS
SELECT customer_id, total_spent
FROM CustomerTotals;

SELECT e.full_name, m.full_name AS manager_name
FROM Employee e
LEFT JOIN Employee m ON e.manager_id = m.emp_id;

SELECT e.full_name, m.full_name AS manager_name
FROM Employee e
JOIN Employee m ON e.emp_id = m.manager_id;

SELECT e.full_name, m.full_name AS manager_name
FROM Employee e
LEFT JOIN Employee m ON e.emp_id = m.emp_id;

SELECT dept_id, dept_name, parent_dept_id
FROM Department
WHERE parent_dept_id = 10;

SELECT dept_id, dept_name, parent_dept_id
FROM Department
WHERE dept_id = 10 OR parent_dept_id IS NOT NULL;
